                  {/* Detail Button - Deep Dive */}
                  <button 
                    onClick={() => onNavigate(value.link)}
                    className={`w-full text-center py-4 border font-bold uppercase tracking-math-wide text-xs transition-all duration-300 rounded-[2px] ${value.color ? `border-[${value.color}] text-[${value.color}] hover:bg-white hover:text-black` : 'border-[#C5A065] text-[#C5A065] hover:bg-[#C5A065] hover:text-sb-green-dark'}`}
                    style={value.color ? { borderColor: '#8A1C1C', color: '#8A1C1C' } : {}}
